from __future__ import annotations

# Curated few-shot examples for the '퓨샷만'/'룰과 퓨샷'/'동적퓨샷' ③ 콤보들 — every
# example below comes from a real row in data/qa_dataset/qa_dataset_frozen.xlsx (golden
# dataset / 예외조건 golden dataset sheets). No synthetic content anywhere.
#
# Leakage-safety scope (2026-08-10 재설계): excludes only the 5 documents actually used
# in the current pilot (DOC-001/003/006/008/012), NOT the full 20-doc benchmark — the
# other 15 benchmark docs (DOC-002/004/005/007/009-011/013-020) are fair game since they
# aren't being scored right now. IMPORTANT: if the pilot doc set ever grows, re-audit this
# file against the new set before trusting precision/recall numbers scored on those docs.
#
# ALL_VIOLATION_CANDIDATES / ALL_EXCEPTION_CANDIDATES are the uncapped, best-first-
# ordered (curated by hand) source pools — used directly by the dynamic-fewshot
# similarity search. VIOLATION_EXAMPLES / EXCEPTION_EXAMPLES are fixed-cap slices of
# those pools for the static hybrid baseline (2 violations / 1 exception per rule,
# matching the original design).
#
# Three isolated sub-axes on top of that baseline (2026-08-10, hybrid_subaxis round —
# each changes exactly one thing, so a pilot can be attributed to one cause):
#   1. "위반 예시를 많이" — VIOLATION_EXAMPLES_RATIO (violations 2->3, exceptions held at
#      baseline's 1). Real-data ceiling: 32/40 rules have >=3 violation candidates; AE-03
#      only has 1 real candidate so stays at 1 there (no synthetic backfill).
#   2. "예외 예시를 많이" — EXCEPTION_EXAMPLES_RATIO (exceptions 1->2, violations held at
#      baseline's 2). Real-data ceiling is tighter here: 23/26 rules have exactly 2
#      exception candidates total, so this slice already exhausts the real pool for most
#      rules (only MI-02/RD-01/RD-03 have more).
#   3. "전체에서 비슷한 예시를 뭐든" — dynamic retrieval (fewshot_retrieval.top_k_examples)
#      over the *uncapped* ALL_VIOLATION_CANDIDATES/ALL_EXCEPTION_CANDIDATES pools, picking
#      whichever example is most similar to the text under review, for both violation and
#      exception examples (see bundled_screen_hybrid_dynamic.py) — counts stay at baseline
#      (2/1), only the selection method changes.

class FewShotExample:
    __slots__ = ("original_text", "rationale")

    def __init__(self, original_text: str, rationale: str) -> None:
        self.original_text = original_text
        self.rationale = rationale


class FewShotException:
    __slots__ = ("original_text", "exception_condition", "rationale")

    def __init__(self, original_text: str, exception_condition: str, rationale: str) -> None:
        self.original_text = original_text
        self.exception_condition = exception_condition
        self.rationale = rationale


